using System;using System.Drawing;using System.Reflection;
namespace FssLauncher {public static class Branding{public static readonly Image Logo=Load();static Image Load(){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("FSS.LauncherLogo"))using(var image=Image.FromStream(stream))return new Bitmap(image);}public static void Draw(Graphics graphics,Rectangle box){float scale=Math.Min(box.Width/(float)Logo.Width,box.Height/(float)Logo.Height);int width=(int)(Logo.Width*scale),height=(int)(Logo.Height*scale);graphics.DrawImage(Logo,new Rectangle(box.X+(box.Width-width)/2,box.Y+(box.Height-height)/2,width,height));}public static Icon AppIcon(){return Icon.ExtractAssociatedIcon(Assembly.GetExecutingAssembly().Location);}}}
